"use strict";(self.webpackChunktil=self.webpackChunktil||[]).push([["2025"],{54938(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>d,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>l});var i=JSON.parse('{"id":"why-big-companies-hunt-for-owners-en","title":"Why Big Companies Are Forever Hunting for an Owner \u2014 From the Problem of Many Hands to Accountability Sinks, and How AI Agents Are Reshuffling the Deck","description":"A Scene Every Engineer Knows","source":"@site/docs/why-big-companies-hunt-for-owners-en.md","sourceDirName":".","slug":"/why-big-companies-hunt-for-owners-en","permalink":"/til/docs/why-big-companies-hunt-for-owners-en","draft":false,"unlisted":false,"editUrl":"https://github.com/alanhc/til/tree/main/docs/why-big-companies-hunt-for-owners-en.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"SLT \u7CFB\u7D71\u7D1A\u6E2C\u8A66","permalink":"/til/docs/what-is-slt-and-why-chip-vendors-care"},"next":{"title":"\u70BA\u4EC0\u9EBC\u5927\u516C\u53F8\u6C38\u9060\u5728\u627E Owner?\u2014\u2014\u5F9E\u773E\u624B\u554F\u984C\u5230\u554F\u8CAC\u9ED1\u6D1E,\u4EE5\u53CA AI Agent \u5982\u4F55\u8B93\u9019\u4E00\u5207\u91CD\u65B0\u6D17\u724C","permalink":"/til/docs/why-big-companies-hunt-for-owners"}}'),o=t(74848),s=t(28453);let a={},r="Why Big Companies Are Forever Hunting for an Owner \u2014 From the Problem of Many Hands to Accountability Sinks, and How AI Agents Are Reshuffling the Deck",l={},h=[{value:"A Scene Every Engineer Knows",id:"a-scene-every-engineer-knows",level:2},{value:"Layer One: Hunting for an Owner Is Rational \u2014 The Problem of Many Hands",id:"layer-one-hunting-for-an-owner-is-rational--the-problem-of-many-hands",level:2},{value:"Layer Two: The Industry&#39;s Solution \u2014 One Name, and Not One More",id:"layer-two-the-industrys-solution--one-name-and-not-one-more",level:2},{value:"Layer Three: The Limits of the Solution \u2014 Some Systems Are Born Many-Handed, and Owners Change",id:"layer-three-the-limits-of-the-solution--some-systems-are-born-many-handed-and-owners-change",level:2},{value:"Layer Four: The People in the Middle \u2014 The Structural Predicament of Boundary Roles",id:"layer-four-the-people-in-the-middle--the-structural-predicament-of-boundary-roles",level:2},{value:"Layer Five: The Dark Side \u2014 When Hunting for an Owner Becomes an Accountability Sink",id:"layer-five-the-dark-side--when-hunting-for-an-owner-becomes-an-accountability-sink",level:2},{value:"Layer Six: The Name Can Be Found; the Ownership Cannot",id:"layer-six-the-name-can-be-found-the-ownership-cannot",level:2},{value:"Layer Seven: The AI Agents Arrive, and the Old Problem Reopens",id:"layer-seven-the-ai-agents-arrive-and-the-old-problem-reopens",level:2},{value:"Closing: Four Questions for the Organization",id:"closing-four-questions-for-the-organization",level:2},{value:"References",id:"references",level:2},{value:"The Professionalism Thread (items 34\u201337)",id:"the-professionalism-thread-items-3437",level:3},{value:"Verification Notes",id:"verification-notes",level:2}];function c(e){let n={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"why-big-companies-are-forever-hunting-for-an-owner--from-the-problem-of-many-hands-to-accountability-sinks-and-how-ai-agents-are-reshuffling-the-deck",children:"Why Big Companies Are Forever Hunting for an Owner \u2014 From the Problem of Many Hands to Accountability Sinks, and How AI Agents Are Reshuffling the Deck"})}),"\n",(0,o.jsx)(n.h2,{id:"a-scene-every-engineer-knows",children:"A Scene Every Engineer Knows"}),"\n",(0,o.jsx)(n.p,{children:"Something breaks. A cross-team meeting convenes. The dashboard on the screen is red. The first thing out of the manager's mouth is not \"what's the root cause?\" It is\u2014"}),"\n",(0,o.jsx)(n.p,{children:'"Who owns this?"'}),"\n",(0,o.jsx)(n.p,{children:"The next twenty minutes are not spent on the fix. They are spent on a precise exercise in boundary-drawing: is this a platform issue or a driver issue? A CI environment problem or a code problem? Our module, or the neighboring team's dependency? Everyone in the room is doing the same thing: proving that the arrow does not point at them."}),"\n",(0,o.jsx)(n.p,{children:"If you have worked at a large company, you know this is not a pathology of any particular firm. It is close to a universal behavioral pattern of large organizations. And here is the interesting part: this pattern has more than forty years of scholarly lineage behind it\u2014it has a name, a theory, a set of solutions, and a complete record of how those solutions fail. More importantly, as AI agents enter the workflow, this old problem is reopening in a new form."}),"\n",(0,o.jsx)(n.h2,{id:"layer-one-hunting-for-an-owner-is-rational--the-problem-of-many-hands",children:"Layer One: Hunting for an Owner Is Rational \u2014 The Problem of Many Hands"}),"\n",(0,o.jsx)(n.p,{children:"Let us first say something in the organization's defense: hunting for an owner is not bureaucratic disease. It is a rational response to a genuine dilemma."}),"\n",(0,o.jsxs)(n.p,{children:["The political scientist Dennis Thompson named this dilemma in 1980: the ",(0,o.jsx)(n.strong,{children:"problem of many hands"}),' [1]. When an outcome is produced by many hands together, no single individual can reasonably be held responsible. Everyone contributed only a small piece; each piece, viewed alone, is beyond reproach; together they add up to a disaster\u2014and when the disaster arrives, you cannot find "the person responsible," because that person does not exist.']}),"\n",(0,o.jsxs)(n.p,{children:["Psychology supplied an even earlier experimental foundation. Darley and Latan\xe9's 1968 bystander experiments demonstrated the ",(0,o.jsx)(n.strong,{children:"diffusion of responsibility"})," effect [2]: the more people present, the lower the probability that any one of them acts. Transposed into an organization, the corollary is brutal\u2014the more recipients on an email, the less likely anyone replies; the more attendees in a meeting, the less likely anyone decides; the more names attached to a project, the less likely anyone is actually watching it."]}),"\n",(0,o.jsx)(n.p,{children:"So when organizations hunt for an owner, they are fighting something close to a law of human physics. Responsibility must converge on a single name before anything moves."}),"\n",(0,o.jsx)(n.h2,{id:"layer-two-the-industrys-solution--one-name-and-not-one-more",children:"Layer Two: The Industry's Solution \u2014 One Name, and Not One More"}),"\n",(0,o.jsxs)(n.p,{children:["The tech industry has developed a mature, institutionalized answer to the problem of many hands, and the versions across companies are strikingly consistent: ",(0,o.jsx)(n.strong,{children:"force the number of accountable people down to one."})]}),"\n",(0,o.jsxs)(n.p,{children:["Apple's version is the ",(0,o.jsx)(n.strong,{children:"DRI (Directly Responsible Individual)"}),": every project, every feature, every action item in every meeting must carry a name. Not a department. Not a team. A name."]}),"\n",(0,o.jsxs)(n.p,{children:["Amazon's version is the ",(0,o.jsx)(n.strong,{children:"single-threaded owner"}),", documented at length in ",(0,o.jsx)(n.em,{children:"Working Backwards"}),' [3]: anything important must have a "single-threaded" leader\u2014someone who does not moonlight, does not simultaneously own anything else, someone who thinks about this one thing every waking moment. Amazon\'s logic: a part-time owner equals no owner, because when two commitments collide, one of them will be sacrificed, and the sacrificed one is, in effect, ownerless.']}),"\n",(0,o.jsx)(n.p,{children:"Even the much-maligned RACI matrix was designed around the same idea: R (responsible for execution) can be many people, but A (ultimately accountable) can hold exactly one name per cell. When RACI fails in practice, it usually is not because the framework is wrong\u2014it is because the organization could not resist filling the A column with a crowd of names, which is to personally invite the problem of many hands back in."}),"\n",(0,o.jsx)(n.p,{children:"Up to this point the story is a positive one: the problem of many hands is real, and the single-owner institution is an effective answer. But it is not that simple\u2014the answer has three structural limits, each backed by solid empirical research."}),"\n",(0,o.jsx)(n.h2,{id:"layer-three-the-limits-of-the-solution--some-systems-are-born-many-handed-and-owners-change",children:"Layer Three: The Limits of the Solution \u2014 Some Systems Are Born Many-Handed, and Owners Change"}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Limit one: not everything can converge on a single name."})}),"\n",(0,o.jsx)(n.p,{children:"The most-cited empirical study of ownership in software engineering is Bird et al.'s 2011 analysis of Windows Vista and Windows 7 [4]: the lower a component's top-owner proportion and the more low-expertise contributors it has, the more pre-release faults and post-release failures it suffers. The paper is routinely invoked as proof that single ownership works\u2014but the same study revealed the other side: low-expertise contributors touching other people's code is, for the most part, not an indiscipline problem but a structural inevitability. They are usually forced to modify someone else's territory because of dependencies and interfaces belonging to their own components. The deeper the coupling between components, the more \"every file has a clear owner\" approaches a fiction."}),"\n",(0,o.jsx)(n.p,{children:'Platform layers, CI pipelines, shared test resources, infrastructure that spans product lines\u2014these "commons" components are the extreme case: every team touches them, every team depends on them, yet hanging any of them on a single individual is a name without substance. This is also why a tradition within the agile movement advocates collective code ownership: rather than maintain a nominal single owner, let the whole team hold the code together, replacing boundaries with norms and tests.'}),"\n",(0,o.jsxs)(n.p,{children:['Collective ownership does have a famous failure mode: it degrades into no ownership, and the many-hands problem returns. But blaming the "collective" is a misdiagnosis. In ',(0,o.jsx)(n.em,{children:"Professionalism: The Third Logic"}),", Freidson argues [34] that work can be coordinated by only three logics\u2014the market, bureaucracy, and professionalism\u2014and that the professional logic holds only under one condition: occupational control. It is the professional community, not the employer and not the price, that defines what counts as competent practice and what risk is acceptable, and that grants practitioners the discretion to exercise that judgment."]}),"\n",(0,o.jsxs)(n.p,{children:["Apply the frame and the three routes to ownership snap into focus. ",(0,o.jsx)(n.strong,{children:"The single owner is the bureaucratic solution"})," (converge responsibility by authority and assignment). ",(0,o.jsx)(n.strong,{children:"Laissez-faire collective ownership is the market solution"})," (whoever has time touches it; individual incentives are left to coordinate themselves)\u2014and it does degrade. ",(0,o.jsx)(n.strong,{children:"The professional solution is the third road"}),": Linux's subsystem maintainer structure, the code-review norms and maintainership of mature open-source projects, any platform team that actually works. None of them runs on a single name, and none of them runs on laissez-faire. They run on community norms, peer review, and practitioner discretion. The parallel to Ostrom's findings on commons governance is exact: a governed commons need not end in tragedy. Tragedy belongs to the ungoverned commons."]}),"\n",(0,o.jsx)(n.p,{children:'The distinction matters to this essay\'s main line, because it yields a positive claim: what commons components need is not a harder search for an owner, but the governance conditions of the professional logic. And those conditions\u2014community norms, peer discretion, authority over what "done well" means\u2014are precisely the first things destroyed by cultures of obedience and by percentage-based management. The single owner is not a universal solution; it is a bureaucratic tool with a bounded domain. Apply a bureaucratic tool where a professional logic is required, and what you get is not converged responsibility. It is a name.'}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Limit two: owners change, and the cost of the change is large enough to quantify."})}),"\n",(0,o.jsx)(n.p,{children:"The owner column on the org chart looks static; in reality it churns continuously\u2014resignations, internal transfers, reorgs, product-line handoffs. The empirical estimates of this cost are unforgiving."}),"\n",(0,o.jsxs)(n.p,{children:["Mockus's 2010 study found that developer-centered measures of organizational volatility\u2014people leaving, structures being reorganized\u2014predict customer-reported defects [5]. In other words, an owner change is itself a leading indicator of defects. Even earlier, in 2009, he had proposed a way to measure ",(0,o.jsx)(n.strong,{children:"succession"})," [6]: when code passes from a departing developer to a successor, the quality of that transfer can be tracked and evaluated\u2014which amounts to admitting that an owner change is not an HR event but an engineering process with costs, risks, and a need for management."]}),"\n",(0,o.jsx)(n.p,{children:'Rigby, Mockus, and colleagues took the accounting to its conclusion in 2016 [7]: using Chrome and a project at Avaya as case studies, they borrowed methods from financial risk analysis to quantify turnover-induced knowledge loss, and found that projects are susceptible to losses more than three times larger than the expected loss\u2014over five times larger in historical simulations. Translated into management language: if you plan owner transitions around the "average handover cost," you are systematically underestimating tail risk. The worst case is not 1.5x the average. It is three to five.'}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Limit three: organizations do not follow their own solution \u2014 part-time owners and percentage-slicing."})}),"\n",(0,o.jsxs)(n.p,{children:['Amazon\'s single-threaded logic is explicit: the owner must not moonlight. Yet in reality, driven by headcount costs, most organizations do exactly the opposite\u2014one person simultaneously holds a system-integration role and a module-owner role, and the standard management artifact is an allocation sheet reading "30% on A, 70% on B." Organizational research has a formal name for this: ',(0,o.jsx)(n.strong,{children:"multiple team membership (MTM)"}),", and it is no fringe phenomenon\u2014Mortensen and Gardner's 2017 survey in ",(0,o.jsx)(n.em,{children:"Harvard Business Review"})," reported that in global companies, belonging to multiple teams at once is the norm for 81% of managers [9]."]}),"\n",(0,o.jsx)(n.p,{children:"The foundational theory here is O'Leary, Mortensen, and Woolley's 2011 model [8]: organizations use MTM to chase a double dividend of productivity and learning, but the structure imposes competing pressures on members' attention and information processing that make it hard to raise both at once\u2014the number and variety of memberships is something to be carefully balanced, not a resource that stacks without limit."}),"\n",(0,o.jsxs)(n.p,{children:["The deeper problem is the metric itself. A percentage assumes attention can be sliced linearly, like machine-hours: invest 30% of the time, harvest 30% of the output. The empirical record rejects that assumption. Zika-Viktorsson and colleagues' 2006 study of multi-project settings introduced the concept of ",(0,o.jsx)(n.strong,{children:"project overload"})," [10]: the fragmentation and frequent switching of multi-project work correlate with psychological stress reactions and impaired competence development\u2014fragmentation eats not only output but growth. In software engineering, Vasilescu et al.'s 2016 large-scale longitudinal study of GitHub [11] found that developer output depends on the balance among project count, focus, and project diversity: multitasking has measurable cognitive limits\u2014the paper's title, ",(0,o.jsx)(n.em,{children:"The Sky Is Not the Limit"}),", is itself the conclusion. The most widely circulated rule of thumb in industry comes from Weinberg: each additional concurrent project costs roughly 20% of one's time to switching. That is a heuristic, not rigorous evidence\u2014but it points in the same direction as the research that followed: switching costs appear on no percentage sheet. They are an invisible tax levied outside the ledger."]}),"\n",(0,o.jsx)(n.p,{children:'And percentage-slicing carries one deeper contradiction, straight back to Amazon\'s logic: when the 30% role and the 70% role collide, the 30% commitment is effectively ownerless. A percentage is not the intensity of a commitment; it is the priority order of its sacrifice\u2014an owner cut in half is not two half-time owners, but two owners each liable to drop to zero at any moment. The allocation sheet manufactures an accounting illusion that "everything is covered by someone." But attention is not an accounting entry.'}),"\n",(0,o.jsxs)(n.p,{children:["Together, the three limits explain a phenomenon large companies routinely overlook: ",(0,o.jsx)(n.strong,{children:"there exists an entire class of roles\u2014systems integration, build/CI operations, cross-team triage, program management\u2014whose actual job content is to keep paying, day after day, for the problem of many hands and the cost of owner change; and the irony is that these are precisely the roles most often percentage-sliced."})," The single-owner institution did not eliminate the many-hands problem. It merely pushed it out to the boundaries between components; and the collisions at those boundaries, the knowledge gaps left after names change, and the invisible tax of switching all need someone to absorb them daily. The existence of these roles is not organizational inefficiency\u2014it is the organization honestly pricing the limits of its own solution. Provided, of course, that the pricing is honest, rather than a pretense that the percentage sheet has already counted the cost."]}),"\n",(0,o.jsx)(n.h2,{id:"layer-four-the-people-in-the-middle--the-structural-predicament-of-boundary-roles",children:"Layer Four: The People in the Middle \u2014 The Structural Predicament of Boundary Roles"}),"\n",(0,o.jsxs)(n.p,{children:["The previous layer said someone is paying for the system. This layer asks how the people doing the paying are faring. The answer: organizational research has studied this position for nearly fifty years, and the findings are remarkably consistent\u2014",(0,o.jsx)(n.strong,{children:"people standing on boundaries suffer penalties that come from the position, not from their performance."})]}),"\n",(0,o.jsxs)(n.p,{children:["Start with how critical the role is. Tushman's foundational 1977 study in ",(0,o.jsx)(n.em,{children:"Administrative Science Quarterly"}),' (345 subjects across 58 projects in R&D laboratories) identified special boundary roles\u2014gatekeepers and liaisons [12]: effective information flow across boundaries is accomplished only by the few individuals who are well connected both internally and externally. In other words, integration and coordination are not "chores anyone can do." They are a scarce capability\u2014the first conclusion of this literature, and the one organizations forget most often.']}),"\n",(0,o.jsxs)(n.p,{children:['But critical does not mean comfortable. Kahn et al.\'s 1964 classic on role conflict [13] describes the predicament of the "focal person": someone on whom multiple role senders\u2014managers, partner teams, downstream customers\u2014simultaneously project expectations. When those expectations are incompatible, the focal person bears role conflict, which, in the original text\'s words, in persistent and extreme form is "not merely irritating" but "identity destroying." Two findings from this research tradition land squarely on the "sandwiched" experience. First, follow-up analyses showed that experienced conflict intensity correlates with the diversity of the role set\u2014people in frequent contact with other parts of the organization experience the strongest conflict, and the greater the organizational distance of the role set (the more levels and departments spanned), the greater the conflict. Second, one of Kahn\'s principal findings: objective conflict converts into subjective strain when the role set is powerful. Stack the two findings: ',(0,o.jsx)(n.strong,{children:"a low-ranked person facing a high-power, high-diversity, high-organizational-distance ring of role senders is the most painful configuration role-conflict theory can describe\u2014and it is the daily reality of systems-integration roles in large companies."})]}),"\n",(0,o.jsxs)(n.p,{children:['Now consider "being challenged." The sociological review of brokerage\u2014Stovel and Shaw, 2012, in the ',(0,o.jsx)(n.em,{children:"Annual Review of Sociology"})," [14]\u2014identifies a fundamental duality: brokerage eases interaction, enables economic activity, and facilitates cooperation; and at the same time it routinely attracts suspicion of self-dealing, accusations of exploitation, and the reproduction of inequality. Being questioned about \"misusing resources\" is a structural interrogation of the broker's position, not of the broker's character: ",(0,o.jsx)(n.strong,{children:"each side can see only the cost you spend on their side; neither side can see the coordination cost you save for the whole"}),"\u2014because when coordination cost is saved, it appears on nobody's report; only when coordination fails does everyone suddenly see you. A middleman's output is inherently counterfactual: the better you do the job, the less anyone knows you did it."]}),"\n",(0,o.jsxs)(n.p,{children:["Finally, the matter of rank\u2014and here the cause runs deeper than any performance system. In ",(0,o.jsx)(n.em,{children:"The System of Professions"}),", Abbott argues [35] that professional standing derives from ",(0,o.jsx)(n.strong,{children:"jurisdiction"}),": an occupation secures its place by winning exclusive control over a body of abstract knowledge, and conflicts between occupations are, at bottom, disputes over jurisdictional boundaries."]}),"\n",(0,o.jsxs)(n.p,{children:["Hold that ruler against the boundary role. Does systems integration own a distinctive body of abstract knowledge? Does it have a credential, an accepted standard of practice, a community entitled to say what counts as integrating well? It does not. It lives in the seams between jurisdictions\u2014every profession declares where its territory ends, and what remains is the integrator's job. ",(0,o.jsx)(n.strong,{children:'A role defined as "outside everyone else\'s jurisdiction" cannot, structurally, possess a jurisdiction of its own.'})," That is the true source of the low rank: not that the work is unimportant, but that no community exists to vouch for its importance."]}),"\n",(0,o.jsxs)(n.p,{children:["The institutional evidence follows. Babcock and colleagues, writing in the ",(0,o.jsx)(n.em,{children:"American Economic Review"})," in 2017, introduced the concept of ",(0,o.jsx)(n.strong,{children:"non-promotable tasks"})," [15]: work that is critical to the organization's functioning but useless to the performer's advancement, and whose allocation is systematically biased\u2014it tends to land on those for whom refusal is most costly. The engineering world's practitioner version is Reilly's \"Being Glue\": the work of cross-team coordination, decomposing ambiguous problems, and making sure nothing falls on the floor is ",(0,o.jsx)(n.em,{children:"glue work"}),', and it carries a cruel asymmetry\u2014the same work, done by a senior person, is called leadership; done by a junior person, it risks being scored at review time as "not technical enough."']}),"\n",(0,o.jsxs)(n.p,{children:["Notice the grammar of that phrase. It does not say you did nothing. It says what you did does not count. ",(0,o.jsx)(n.strong,{children:"That is a jurisdictional ruling, delivered in the form of a performance review."})," And so the loop closes: ",(0,o.jsx)(n.strong,{children:'coordination work has no jurisdiction to vouch for it \u2192 it does not count toward promotion \u2192 rank stays put \u2192 low rank makes the "misused resources" challenge easier to sustain \u2192 and a sustained challenge further suppresses the visibility of the work.'})," Every step of the loop is locally rational for each party; the sum is the systematic depreciation of the organization's scarcest role."]}),"\n",(0,o.jsx)(n.p,{children:"The conclusion of this layer deserves to be said plainly: if you find yourself as the person in the middle, what the literature offers you is not consolation but a diagnosis\u2014the conflict, the suspicion, and the stalled rank you experience are structural products of the boundary position, written into the textbooks fifty years ago. The question that actually deserves to be challenged is this: why does an organization that runs on its boundary roles place those roles in the positions with the least power?"}),"\n",(0,o.jsx)(n.h2,{id:"layer-five-the-dark-side--when-hunting-for-an-owner-becomes-an-accountability-sink",children:"Layer Five: The Dark Side \u2014 When Hunting for an Owner Becomes an Accountability Sink"}),"\n",(0,o.jsxs)(n.p,{children:["In 2024, the economist Dan Davies introduced a concept that has spread rapidly through management circles: the ",(0,o.jsx)(n.strong,{children:"accountability sink"})," [16]."]}),"\n",(0,o.jsx)(n.p,{children:"Davies's observation: large organizations evolve structures that delegate decisions to rulebooks, standard procedures, or computer systems, so that \"the person who decided\" vanishes from the system. When your flight is canceled, your insurance claim denied, your purchase request bounced, the person behind the counter tells you: \"It's the system. There's nothing I can do.\" They are telling the truth. The decision really wasn't theirs\u2014but it also wasn't made by anyone you can find. Responsibility has been sucked into a sink, never to return."}),"\n",(0,o.jsxs)(n.p,{children:["Davies's key insight: for an accountability sink to hold, one link must be severed\u2014",(0,o.jsx)(n.strong,{children:"feedback from the people affected by a decision must be unable to reach the system that made it."})," With the feedback loop cut, errors can be neither attributed nor corrected."]}),"\n",(0,o.jsxs)(n.p,{children:["And here comes an uncomfortable inference: ",(0,o.jsx)(n.strong,{children:"organizations' enthusiasm for finding an owner is sometimes not about solving the problem, but about pre-arranging where the blame will land."})," The public-administration scholar Christopher Hood documented this behavior systematically in ",(0,o.jsx)(n.em,{children:"The Blame Game"}),' [17]: organizations carefully engineer structures to deflect and distribute blame, and "designating an owner" is the cheapest blame insurance available\u2014when things go wrong, the sink is already dug and the name already filled in.']}),"\n",(0,o.jsx)(n.p,{children:"This explains the strange scene in the meeting room: why everyone spends twenty minutes drawing boundaries instead of fixing the problem. Because everyone intuits that being designated the owner at that moment confers not resources and authority, but a pre-paid blame invoice."}),"\n",(0,o.jsx)(n.h2,{id:"layer-six-the-name-can-be-found-the-ownership-cannot",children:"Layer Six: The Name Can Be Found; the Ownership Cannot"}),"\n",(0,o.jsx)(n.p,{children:"Here lies a pair of concepts organizations chronically conflate but scholarship keeps sharply distinct."}),"\n",(0,o.jsxs)(n.p,{children:["The management scholars Pierce, Kostova, and Dirks, in their work on ",(0,o.jsx)(n.strong,{children:"psychological ownership"}),' [18], point out that "being designated the owner" and "genuinely feeling this is mine" are two different things. The former is a label on an org chart; the latter is a psychological state\u2014and only the latter produces the behavior organizations actually want: proactive maintenance, long-term investment, treating the system\'s health as one\'s own concern.']}),"\n",(0,o.jsx)(n.p,{children:"Psychological ownership has three wellsprings: a sense of control over the target, intimate knowledge of it, and investment of the self into it. Note what the three have in common: none of them can be produced by assignment. You can hang a legacy system on an engineer's name in the org chart, but if he has no control over it (changes require five layers of approval), no deep knowledge of it (the documentation is lost, the original authors gone), and no self invested in it (he inherited it last year), then what you have obtained is an owner's name and zero ownership."}),"\n",(0,o.jsxs)(n.p,{children:["Here is the true dilemma of the owner hunt: ",(0,o.jsx)(n.strong,{children:"what the organization needs is ownership, but the institution can only manufacture owners."}),' The name gets filled in, the sink gets dug, but the person who "thinks about this one thing every waking moment" does not materialize from an assignment email.']}),"\n",(0,o.jsx)(n.h2,{id:"layer-seven-the-ai-agents-arrive-and-the-old-problem-reopens",children:"Layer Seven: The AI Agents Arrive, and the Old Problem Reopens"}),"\n",(0,o.jsx)(n.p,{children:"The six layers above are the story before AI. The arrival of agentic AI is resurrecting this forty-year-old problem in a new form."}),"\n",(0,o.jsxs)(n.p,{children:["The philosopher Andreas Matthias predicted it in 2004, under the name ",(0,o.jsx)(n.strong,{children:"responsibility gap"})," [19]: traditional responsibility ascription rests on two conditions\u2014control and foreseeability. You controlled the behavior, you could foresee the consequences, therefore you are responsible. But the behavior of learning, autonomous systems exceeds what their designers can predict; when a system does something no one instructed and no one could foresee, the chain of responsibility snaps."]}),"\n",(0,o.jsx)(n.p,{children:"Santoni de Sio and Mecacci went further in 2021 [20]: the responsibility gap that AI brings is not one problem but at least four interrelated gaps\u2014culpability, moral accountability, public accountability, and active responsibility\u2014and the introduction of AI sharpens the original problem of many hands, because data and decisions are introduced and processed at ever more nodes along the chain, making it ever harder for those affected to find whom to ask."}),"\n",(0,o.jsx)(n.p,{children:"Translate the abstraction into the language of the engineering floor:"}),"\n",(0,o.jsx)(n.p,{children:'An AI agent in your CI pipeline autonomously fixes a bug, opens a PR, gets merged into production\u2014and three weeks later it blows up. Now, how do you answer the meeting-room question, "who owns this?" The person who wrote the prompt? The manager who approved the agent\'s rollout? The engineer who reviewed the PR (he spent ninety seconds)? The model vendor? Or the person listed as "agent owner," who neither wrote that code nor ever read it?'}),"\n",(0,o.jsxs)(n.p,{children:["The organization's instinct is to reuse the old solution: find an owner, hang the agent on his name. But that is exactly the problem\u2014",(0,o.jsx)(n.strong,{children:"this owner is being asked to take full responsibility for output he did not write, did not read, and cannot fully predict."})]}),"\n",(0,o.jsxs)(n.p,{children:["At this point an objection must be met head-on, because it will come from precisely the readers most worth persuading: ",(0,o.jsx)(n.strong,{children:"isn't that the definition of a professional?"})," A structural engineer stamps drawings she did not draft. An attending physician answers for a resident's decisions. A captain is responsible for the entire aircraft and cannot predict the state of every engine. A profession ",(0,o.jsx)(n.em,{children:"is"})," the acceptance of consequences beyond one's individual control. By the logic above, every profession on earth is hollow."]}),"\n",(0,o.jsxs)(n.p,{children:["The objection holds\u2014and answering it sharpens the argument. Return to Freidson's three logics [34]. A professional can answer for outcomes she did not fully control because three things are in place at once: she has the power to refuse to stamp; the standard of competent practice comes from her professional community rather than her employer; and licensure makes her responsibility commensurate with her authority. Responsibility may exceed control. It may do so only when ",(0,o.jsx)(n.strong,{children:"authority also exceeds assignment."})]}),"\n",(0,o.jsxs)(n.p,{children:["So what has the organization done to the agent's owner? It has taken the accountability of a profession and kept the control of a bureaucracy. This owner cannot veto the agent, cannot redraw its boundaries, cannot define what counts as acceptable output\u2014but when it fails, his is the name. Evetts gives the deformation its precise name [36]: this is ",(0,o.jsx)(n.strong,{children:"organizational professionalism"}),"\u2014the discourse of the professional imposed from above by managers, operating through rational-legal decision-making, hierarchical authority, and standardized procedure. Its counterpart is ",(0,o.jsx)(n.strong,{children:"occupational professionalism"}),"\u2014control exercised from within the professional community, encompassing practitioner discretion and self-regulation. One word, two opposite directions of power."]}),"\n",(0,o.jsxs)(n.p,{children:['The correct diagnosis, then, is not "he cannot predict it, so he cannot own it"\u2014that road wrongly indicts every real profession. The correct diagnosis is: ',(0,o.jsx)(n.strong,{children:"he has no authority, so he cannot own it."})," He has the owner's name, but he cannot possibly have the three wellsprings of psychological ownership: control (he cannot stop the agent or redraw its boundaries), intimate knowledge (the output volume exceeds what a human can read), invested self (it is not his work). This is not hollow professionalism. It is professionalism with the occupational autonomy extracted\u2014",(0,o.jsx)(n.strong,{children:"the responsibility is professional, the authority is bureaucratic."})," Decouple the two, and ownership is structurally guaranteed to be empty."]}),"\n",(0,o.jsx)(n.p,{children:'And the handover cost from Layer Three recurs here in a worse form: the agent itself never resigns, but the agent\'s owner does. When a human owner hands over a system he wrote himself, he at least has documentation, commit history, and the decision context in his head to transfer; when he hands over an agent plus its accumulated configuration, prompts, boundary rules, and exception lists\u2014a bundle even he only partially understands\u2014the "three-to-five-times" tail risk from the succession research is probably still an underestimate.'}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:'And when organizations begin demanding that employees process work "in parallel" and supervise multiple agents "in parallel," percentage accounting loses whatever residual validity it had.'})}),"\n",(0,o.jsx)(n.p,{children:'The first problem is cognitive. Dual-task research in psychology long ago established that human central cognitive processing has a serial bottleneck [29]: two tasks that require thought cannot truly run at once; they can only queue. Rubinstein, Meyer, and Evans\'s 2001 experiments measured the price of switching [30]: every switch between tasks carries a measurable time cost, and the more complex and less familiar the tasks, the higher the cost. What we call "parallel processing" is, cognitively, high-frequency serial switching plus a tax on every switch\u2014a tax for which the percentage sheet has no line item.'}),"\n",(0,o.jsxs)(n.p,{children:['The second problem is that "supervising multiple autonomous systems" has already been quantified\u2014just in another field. Human-robot interaction research, in the context of unmanned vehicles, developed the ',(0,o.jsx)(n.strong,{children:"fan-out model"}),": Olsen and Wood proposed at CHI 2004 [31] that the number of autonomous systems one person can operate simultaneously is governed by the ratio between the systems' neglect time (how long each can be left alone) and interaction time (how long each intervention takes); robot attention demand and interaction effort are the field's standard measures. Two findings from that literature should alarm anyone in the agent era: first, once later models incorporated wait times and attention-switching costs, feasible fan-out proved lower than the original estimates; second, even within this specialist field, methods for predicting \"how many can one person supervise\" have produced inconsistent results to this day\u2014",(0,o.jsx)(n.strong,{children:"the thing the drone field could not pin down in twenty years, the management floor settles with one percentage sheet."})]}),"\n",(0,o.jsxs)(n.p,{children:["The third problem is the temporal structure. Supervisory work is bursty and interrupt-driven: when an agent needs a human is not decided by the owner's calendar. Mark and colleagues' classic 2008 study of interrupted work found [32] that interrupted workers compensate by finishing faster\u2014at the price of significantly higher stress, frustration, and time pressure. And the basic result of queueing theory (brought systematically into product-development management by Reinertsen [33]) says: as resource utilization approaches 100%, waiting time explodes nonlinearly\u2014filling a person to 100% by percentages guarantees that every agent he supervises will be standing in line at the moment it needs a human. ",(0,o.jsx)(n.strong,{children:"Agents can run in parallel. Their owner's attention cannot be given in parallel."})]}),"\n",(0,o.jsx)(n.p,{children:'Put the three together and the conclusion is: percentage accounting was merely inaccurate in the era of human multitasking; in the era of agent supervision it is measuring the wrong dimension. It measures how time is sliced, while the true cost of supervisory work lies in the distribution of interruptions and queueing delays. The right question is not "what percent of your time goes to each thing?" but "after your interaction times are summed, how much neglect tolerance does this system have left?"\u2014and the latter, at present, appears on no management report anywhere.'}),"\n",(0,o.jsx)(n.p,{children:"And Davies's warning turns piercing at this moment: delegating decisions to algorithms is the most convenient way to build an accountability sink. If organizations do not redesign accountability, AI agents will not solve the problem of many hands\u2014they will become the largest hand in history: a hand with no name, no psychological state, and no way to be blamed. And the human owner whose name hangs on it is merely the signboard at the sink's entrance."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Finally, the arrival of AI hands individual employees a brand-new double bind."})}),"\n",(0,o.jsx)(n.p,{children:'Many organizations now issue two directives to their employees at once. The first is explicit: "spend X% of your time studying AI." But Layer Three already established that percentages are an accounting illusion\u2014and of all activities, learning happens to be the one most sensitive to time fragmentation. Zika-Viktorsson\'s project-overload research showed long ago [10] that what fragmentation damages most is not just output but competence development itself. "AI research time" sliced into slivers buys not research, but a record of having researched.'}),"\n",(0,o.jsxs)(n.p,{children:["The second directive is implicit, and points the other way. Reif, Larrick, and Soll, in four preregistered experiments (4,439 participants) published in ",(0,o.jsx)(n.em,{children:"PNAS"})," in 2025, found [21]: people who use AI at work both anticipate and receive negative social evaluations of their competence and motivation\u2014they are seen as lazier, less capable, more replaceable\u2014and the penalty holds consistently across occupation, age, and gender. More ironic still: the harshest evaluations come from assessors who do not use AI themselves. The authors frame it as a paradox: a productivity-enhancing tool that simultaneously damages its user's professional reputation. The consequence is predictable\u2014participants were significantly less willing to disclose their AI use to managers and colleagues."]}),"\n",(0,o.jsxs)(n.p,{children:["Seen through professionalism, this penalty is not irrational at all: ",(0,o.jsx)(n.strong,{children:"it is a professional norm being enforced."}),' "The work you hand over must issue from your own hand" is a core promise of professional identity, and using AI violates it. That reading explains the study\'s two most curious findings\u2014why the penalty holds uniformly across occupation, age, and gender (it targets not a demographic but a norm), and why the harshest assessors are the non-users (the guardians of a norm are usually the ones most bound by it).']}),"\n",(0,o.jsxs)(n.p,{children:["And it points to a threat deeper than replacement. Return to Freidson's definition: professionalism is a third logic precisely because the occupation holds authority over what counts as competent. As that standard comes to be set by model capability\u2014as human output falls permanently behind the agent's, as the baseline for \"good enough\" is reset by a tool\u2014the professional community loses that authority. ",(0,o.jsx)(n.strong,{children:"AI's central threat to a profession is not that it replaces practitioners. It is that it strips the occupation of its authority to define competence; and once that authority is gone, the third logic collapses, leaving only the market and the bureaucracy."})," Which is what this entire essay, from its first layer onward, has been about: how the market and the bureaucracy handle responsibility. One does it with a price. The other does it with a name."]}),"\n",(0,o.jsxs)(n.p,{children:['Stack the two directives and you have a double bind in Bateson\'s sense [22]: "you must adopt AI" and "adopting AI will be punished" hold simultaneously, and\u2014this is Argyris\'s classic description of organizational defensive routines [23]\u2014',(0,o.jsx)(n.strong,{children:"the contradiction itself is undiscussable."}),' In the vast majority of organizations, no one can say in a meeting, "we are demanding that employees learn AI while punishing them for using it"\u2014because the person who points out a mixed message is usually treated as the problem. Argyris laid out the full defensive routine: send inconsistent messages, deny the inconsistency, then make the denial itself undiscussable.']}),"\n",(0,o.jsxs)(n.p,{children:["But Argyris described undiscussability without explaining how it is ",(0,o.jsx)(n.strong,{children:"manufactured"}),'. Fournier supplies that piece [37]: when the discourse of the "professional" is exported into occupational domains not traditionally counted as professions, it becomes a disciplinary logic that governs conduct at a distance\u2014inscribing autonomous practice, in advance, within a network of accountability. Her central claim rewards slow reading: professional labor is autonomous labor in which the conditions of autonomy have already been inscribed into the very notion of "professional competence." You are free to act, provided your free choices happen to be the ones professionalism requires.']}),"\n",(0,o.jsxs)(n.p,{children:["With that piece in place, a gap in the preceding layers finally closes. Everything so far has described how structures impose; nothing has explained why individuals consent. The answer is that ",(0,o.jsx)(n.strong,{children:"the cost of refusal is being called unprofessional."})," Babcock's finding\u2014that non-promotable tasks flow toward those for whom refusal is most costly\u2014takes a concrete form in engineering organizations: the cost of refusal is the loss of professional identity. Glue work needs no coercion; it needs only that declining it look like a character flaw. The percentage sheet needs no defense; it needs only that complaining about it look petty. And the contradiction is undiscussable because whoever names it pays, first, the price of seeming unprofessional."]}),"\n",(0,o.jsxs)(n.p,{children:["This line cuts deeper than Argyris, because it requires no one's bad faith. Nobody is operating the mechanism. ",(0,o.jsx)(n.strong,{children:"Professionalism is at once the organization's cheapest instrument of discipline and the employee's only language of resistance"}),'\u2014when you say "this isn\'t professional," you are reaching for the very key that locks you in.']}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"And resource scarcity twists the double bind tighter."})," When headcount is already short, every minute an employee spends on AI draws simultaneous challenge from two directions\u2014and the phrasing of those challenges is strikingly uniform across industries, each with a classic theory behind it."]}),"\n",(0,o.jsxs)(n.p,{children:["The first challenge comes from the management side: \"You can't even finish your core work\u2014why are you fiddling with AI?\" This is the structural bias March described in his 1991 classic of organizational learning [24]: organizations naturally favor exploitation (harvesting certain, near-term returns from existing capabilities) at the expense of exploration (building new capabilities with distant, uncertain returns)\u2014because exploration's payoffs are further away in time and more dispersed in probability, it loses every round of the resource competition. Nohria and Gulati's 1996 empirical work adds the role of slack [25]: slack (resources in excess of the minimum necessary) has an inverted-U relationship with innovation\u2014",(0,o.jsx)(n.strong,{children:"in the absence of slack, experimentation cannot be sustained at all, because experimental outcomes are inherently high-variance."})," Translated: a resource-starved organization telling its employees to \"study AI\" is asking them to do something statistically guaranteed to fail a few times, inside an environment structurally unable to tolerate failure. Mullainathan and Shafir's research on scarcity [26] explains the management side's field of vision: scarcity tunnels attention\u2014people whose bandwidth is taxed by the urgent are structurally unable to see the value of long-term investment. Managers do not fail to understand that AI matters; scarcity ensures that everyone sees only the core work inside the tunnel."]}),"\n",(0,o.jsxs)(n.p,{children:["The second challenge comes from peers: \"How come you have spare time for AI?\" This belongs to a different lineage. Adams's equity theory [27] holds that people continuously compare their input\u2013output ratios with others', and perceived inequity triggers strong corrective motivation\u2014in an everyone-is-firefighting environment, any visible time spent on non-firefighting work is read directly as \"your load is lighter than mine,\" regardless of whether it was assigned. Bellezza and colleagues' 2017 research [28] adds the cultural layer: in a workplace culture where busyness itself has become a status symbol, visible non-core time is not merely a load signal\u2014it is a status violation. So in a scarce organization, the directive to \"spend X% on AI\" leaves its executor besieged on three fronts: the management side's exploitation bias, peers' equity comparisons, and one's own scarcity-tunneled attention\u2014",(0,o.jsx)(n.strong,{children:"the moment the directive is issued, the organization has already deployed every mechanism required to punish its execution."})]}),"\n",(0,o.jsxs)(n.p,{children:['And here the double bind converges with the article\'s main line: when AI adoption stalls, the organization finds an owner and asks "why isn\'t this moving?"; when AI use goes wrong, the organization finds an owner and asks "why did you use it?" The same person can perfectly well be the owner of both questions. Facing this configuration, the individually rational response is shadow AI\u2014use it quietly, disclose nothing\u2014and shadow AI happens to be the worst case for any accountability structure: ',(0,o.jsx)(n.strong,{children:"usage maximized, accountability minimized."})," With its own evaluation culture, the organization has pushed AI use into the sink with its own hands."]}),"\n",(0,o.jsx)(n.h2,{id:"closing-four-questions-for-the-organization",children:"Closing: Four Questions for the Organization"}),"\n",(0,o.jsx)(n.p,{children:"This essay does not offer a complete solution\u2014that would take another essay. But before an organization rushes to assign an owner to every AI agent, three questions deserve answers first."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"First: are you looking for an owner, or for a place to park the blame?"})," The test is simple: look at whether the owner receives authority or only obligations. If he has the power to stop the agent, to change the agent's boundaries, to veto the agent's output\u2014that is ownership. If he is merely the person who writes the report when things go wrong, that is the signboard on an accountability sink."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Second: does your accountability structure preserve the feedback link?"})," Davies's criterion bears repeating: a sink exists precisely where feedback is severed. The people affected by the agent's output\u2014downstream teams, customers, engineers carpet-bombed with review requests\u2014can their feedback genuinely change how the agent operates? If not, you are already digging."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Third: what do you actually want\u2014a name, or a psychological state?"})," If the latter, assignment is not enough. Psychological ownership grows from control, knowledge, and invested self\u2014which means the agent's owner must participate in designing the agent's boundaries, must have the tools to see through the agent's behavior, must have the time to cultivate it as his own work. That is expensive. But a hollow owner is more expensive; the invoice merely arrives later."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:'Fourth: when you say "professional," who does the defining?'}),' This is the least comfortable question, and it underwrites the first three. If "professional" means that practitioners hold discretion over their own work and a voice in what counts as doing it well, then professionalism is the source of ownership. If "professional" is merely the adjective that gets someone to accept the work nobody wants and not complain about it, then professionalism is the lubricant of an accountability sink. One word, two opposite uses, and exactly one criterion separates them: ',(0,o.jsx)(n.strong,{children:"who holds the authority to define it."})," An organization that wants its people to answer for an agent's output the way professionals answer for their work must let them refuse the way professionals refuse\u2014it must let them say, \"I'm not signing this.\""]}),"\n",(0,o.jsx)(n.p,{children:'Forty years ago, Thompson told us the problem of many hands cannot be solved, only managed. The tech industry managed it for thirty years with DRIs and single-threaded owners. Now AI agents walk into the office carrying the most hands in history\u2014and organizations will either redesign accountability, or discover that the answer to "who owns this?" is becoming "no one\u2014and this time, truly no one."'}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.em,{children:"The situations described in this essay are composite depictions of cross-industry patterns; every scenario has counterparts in the empirical samples of the cited literature (spanning Windows, Chrome, Avaya, GitHub, and surveys of managers in global companies), and none refers to any specific organization or individual."})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"references",children:"References"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Thompson, D. F. (1980). ",(0,o.jsx)(n.em,{children:"Moral Responsibility of Public Officials: The Problem of Many Hands."})," American Political Science Review, 74(4), 905\u2013916. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.2307/1954312",children:"https://doi.org/10.2307/1954312"}),'\n\u2014 Origin of the "problem of many hands": when an outcome is produced by many actors together, no individual can reasonably be held responsible.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Darley, J. M., & Latan\xe9, B. (1968). ",(0,o.jsx)(n.em,{children:"Bystander Intervention in Emergencies: Diffusion of Responsibility."})," Journal of Personality and Social Psychology, 8(4), 377\u2013383.\n\u2014 Classic experiments on diffusion of responsibility: the more people present, the lower the probability any individual acts."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Bryar, C., & Carr, B. (2021). ",(0,o.jsx)(n.em,{children:"Working Backwards: Insights, Stories, and Secrets from Inside Amazon."})," St. Martin's Press.\n\u2014 Documents Amazon's single-threaded leadership: important initiatives require a single, non-moonlighting owner."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Bird, C., Nagappan, N., Murphy, B., Gall, H., & Devanbu, P. (2011). ",(0,o.jsx)(n.em,{children:"Don't Touch My Code! Examining the Effects of Ownership on Software Quality."})," ESEC/FSE '11, 4\u201314. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1145/2025113.2025119",children:"https://doi.org/10.1145/2025113.2025119"}),"\n\u2014 Windows Vista/7 evidence: lower top-owner proportion and more low-expertise contributors correlate with more pre-release faults and post-release failures; also finds that low-expertise contributions stem largely from structural causes (dependencies, interfaces) and cannot simply be forbidden."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Mockus, A. (2010). ",(0,o.jsx)(n.em,{children:"Organizational Volatility and Its Effects on Software Defects."})," FSE '10, 117\u2013126. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1145/1882291.1882311",children:"https://doi.org/10.1145/1882291.1882311"}),"\n\u2014 Developer-centered measures of organizational change (departures, reorganizations) predict customer-reported defects."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Mockus, A. (2009). ",(0,o.jsx)(n.em,{children:"Succession: Measuring Transfer of Code and Developer Productivity."})," ICSE '09.\n\u2014 Proposes measuring code succession between developers, treating owner change as a trackable, assessable knowledge-transfer process rather than a mere personnel event."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Rigby, P. C., Zhu, Y. C., Donadelli, S. M., & Mockus, A. (2016). ",(0,o.jsx)(n.em,{children:"Quantifying and Mitigating Turnover-Induced Knowledge Loss: Case Studies of Chrome and a Project at Avaya."})," ICSE '16, 1006\u20131016. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1145/2884781.2884851",children:"https://doi.org/10.1145/2884781.2884851"}),"\n\u2014 Applies financial risk-analysis methods to turnover-induced knowledge loss (measured via abandoned source files): projects are susceptible to losses more than three times the expected loss, over five times in historical simulations; reviews prior evidence that survivors and newcomers maintaining abandoned code lose productivity and err more."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["O'Leary, M. B., Mortensen, M., & Woolley, A. W. (2011). ",(0,o.jsx)(n.em,{children:"Multiple Team Membership: A Theoretical Model of Its Effects on Productivity and Learning for Individuals and Teams."})," Academy of Management Review, 36(3), 461\u2013478.\n\u2014 Foundational MTM theory: organizations pursue productivity and learning through multiple team membership, but the structure imposes competing pressures on attention and information; number and variety of memberships require careful balancing."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Mortensen, M., & Gardner, H. K. (2017). ",(0,o.jsx)(n.em,{children:"The Overcommitted Organization."})," Harvard Business Review, 95(5), 58\u201365.\n\u2014 Reports that multiple team membership is the norm for 81% of managers in global companies; examines how organizational overcommitment erodes team effectiveness."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Zika-Viktorsson, A., Sundstr\xf6m, P., & Engwall, M. (2006). ",(0,o.jsx)(n.em,{children:"Project Overload: An Exploratory Study of Work and Management in Multi-Project Settings."}),' International Journal of Project Management, 24(5), 385\u2013394.\n\u2014 Introduces "project overload": fragmentation and frequent switching in multi-project work correlate with psychological stress reactions and impaired competence development.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Vasilescu, B., Blincoe, K., Xuan, Q., Casalnuovo, C., Damian, D., Devanbu, P., & Filkov, V. (2016). ",(0,o.jsx)(n.em,{children:"The Sky Is Not the Limit: Multitasking Across GitHub Projects."})," ICSE '16, 994\u20131005. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1145/2884781.2884875",children:"https://doi.org/10.1145/2884781.2884875"}),"\n\u2014 Large-scale longitudinal GitHub evidence: developer output depends on the balance among project count, focus, and project diversity; multitasking has measurable cognitive limits."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Tushman, M. L. (1977). ",(0,o.jsx)(n.em,{children:"Special Boundary Roles in the Innovation Process."})," Administrative Science Quarterly, 22(4), 587\u2013605.\n\u2014 Foundational boundary-spanning study (345 subjects, 58 projects in R&D labs): identifies gatekeepers and liaisons; effective cross-boundary information flow is accomplished only by the few individuals well connected both internally and externally."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Kahn, R. L., Wolfe, D. M., Quinn, R. P., Snoek, J. D., & Rosenthal, R. A. (1964). ",(0,o.jsx)(n.em,{children:"Organizational Stress: Studies in Role Conflict and Ambiguity."})," Wiley.\n\u2014 Original role-conflict theory: the focal person bears incompatible expectations from multiple role senders; a principal finding is that objective conflict converts to subjective strain when the role set is powerful; follow-up research shows conflict rises with role-set diversity and organizational distance."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Stovel, K., & Shaw, L. (2012). ",(0,o.jsx)(n.em,{children:"Brokerage."})," Annual Review of Sociology, 38, 139\u2013158.\n\u2014 Sociological review of brokerage: a fundamental duality\u2014brokerage eases interaction, economic activity, and cooperation, while routinely attracting suspicion of self-dealing, accusations of exploitation, and the amplification of inequality."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Babcock, L., Recalde, M. P., Vesterlund, L., & Weingart, L. (2017). ",(0,o.jsx)(n.em,{children:"Gender Differences in Accepting and Receiving Requests for Tasks with Low Promotability."}),' American Economic Review, 107(3), 714\u2013747.\n\u2014 Introduces "non-promotable tasks": work critical to the organization but useless for the performer\'s advancement, systematically allocated toward those for whom refusal is most costly.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Davies, D. (2024). ",(0,o.jsx)(n.em,{children:"The Unaccountability Machine: Why Big Systems Make Terrible Decisions\u2014And How the World Lost Its Mind."}),' Profile Books.\n\u2014 Introduces the "accountability sink": organizations absorb decision responsibility into rulebooks, standard procedures, or computer systems, severing the feedback link between decision-makers and those affected, making errors unattributable and uncorrectable.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Hood, C. (2011). ",(0,o.jsx)(n.em,{children:"The Blame Game: Spin, Bureaucracy, and Self-Preservation in Government."})," Princeton University Press.\n\u2014 Systematic account of how organizations engineer structures to deflect and distribute blame (blame avoidance)."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Pierce, J. L., Kostova, T., & Dirks, K. T. (2001). ",(0,o.jsx)(n.em,{children:"Toward a Theory of Psychological Ownership in Organizations."})," Academy of Management Review, 26(2), 298\u2013310. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.5465/amr.2001.4378028",children:"https://doi.org/10.5465/amr.2001.4378028"}),"\n\u2014 Psychological ownership theory: distinguishes the designated owner from the genuine feeling of ownership, which grows from control, intimate knowledge, and investment of self\u2014none producible by assignment."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Matthias, A. (2004). ",(0,o.jsx)(n.em,{children:"The Responsibility Gap: Ascribing Responsibility for the Actions of Learning Automata."})," Ethics and Information Technology, 6(3), 175\u2013183. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1007/s10676-004-3422-1",children:"https://doi.org/10.1007/s10676-004-3422-1"}),'\n\u2014 Original "responsibility gap" paper: when learning autonomous systems act beyond predictable bounds, the traditional conditions for responsibility ascription (control and foreseeability) break down.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Santoni de Sio, F., & Mecacci, G. (2021). ",(0,o.jsx)(n.em,{children:"Four Responsibility Gaps with Artificial Intelligence: Why They Matter and How to Address Them."})," Philosophy & Technology, 34, 1057\u20131084. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1007/s13347-021-00450-x",children:"https://doi.org/10.1007/s13347-021-00450-x"}),"\n\u2014 Argues the AI responsibility gap comprises four interrelated gaps (culpability, moral accountability, public accountability, active responsibility) and that AI's introduction sharpens the problem of many hands."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Reif, J. A., Larrick, R. P., & Soll, J. B. (2025). ",(0,o.jsx)(n.em,{children:"Evidence of a Social Evaluation Penalty for Using AI."})," Proceedings of the National Academy of Sciences, 122(19), e2426766122. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1073/pnas.2426766122",children:"https://doi.org/10.1073/pnas.2426766122"}),"\n\u2014 Four preregistered experiments (N = 4,439): people who use AI at work anticipate and receive negative evaluations of competence and motivation (lazier, less capable, more replaceable), consistent across occupation, age, and gender; the harshest evaluators are those who do not use AI themselves; participants were consequently less willing to disclose AI use."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Bateson, G., Jackson, D. D., Haley, J., & Weakland, J. (1956). ",(0,o.jsx)(n.em,{children:"Toward a Theory of Schizophrenia."}),' Behavioral Science, 1(4), 251\u2013264.\n\u2014 Original "double bind" concept: an individual receives contradictory injunctions and can neither discuss the contradiction nor leave the situation. This essay borrows the structure to describe organizations\' contradictory demands around AI adoption, without invoking its original clinical context.']}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Argyris, C. (1990). ",(0,o.jsx)(n.em,{children:"Overcoming Organizational Defenses: Facilitating Organizational Learning."})," Allyn & Bacon.\n\u2014 Classic on organizational defensive routines: organizations send mixed messages, deny the inconsistency, and render the denial undiscussable, blocking organizational learning."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["March, J. G. (1991). ",(0,o.jsx)(n.em,{children:"Exploration and Exploitation in Organizational Learning."})," Organization Science, 2(1), 71\u201387. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1287/orsc.2.1.71",children:"https://doi.org/10.1287/orsc.2.1.71"}),"\n\u2014 Foundational framework: organizations naturally favor exploitation (certain, near-term returns) at the expense of exploration (distant, uncertain returns), because exploration's payoffs lose systematically in every resource competition."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Nohria, N., & Gulati, R. (1996). ",(0,o.jsx)(n.em,{children:"Is Slack Good or Bad for Innovation?"})," Academy of Management Journal, 39(5), 1245\u20131264.\n\u2014 Empirical inverted-U between slack (resources beyond the minimum necessary) and innovation: without slack, experimentation cannot be sustained because outcomes are high-variance; too much slack erodes discipline."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Mullainathan, S., & Shafir, E. (2013). ",(0,o.jsx)(n.em,{children:"Scarcity: Why Having Too Little Means So Much."})," Times Books.\n\u2014 Psychology of scarcity: scarcity tunnels attention and taxes cognitive bandwidth, causing systematic neglect of long-term investment outside the tunnel."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Adams, J. S. (1965). ",(0,o.jsx)(n.em,{children:"Inequity in Social Exchange."})," In L. Berkowitz (Ed.), Advances in Experimental Social Psychology (Vol. 2, pp. 267\u2013299). Academic Press.\n\u2014 Original equity theory: people continuously compare input\u2013output ratios with others; perceived inequity triggers strong corrective motivation."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Bellezza, S., Paharia, N., & Keinan, A. (2017). ",(0,o.jsx)(n.em,{children:"Conspicuous Consumption of Time: When Busyness and Lack of Leisure Become a Status Symbol."})," Journal of Consumer Research, 44(1), 118\u2013138.\n\u2014 Evidence on busyness as a status symbol: busyness and lack of leisure are read as signals of competence and scarcity, so visible spare time carries a status cost."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Pashler, H. (1994). ",(0,o.jsx)(n.em,{children:"Dual-Task Interference in Simple Tasks: Data and Theory."})," Psychological Bulletin, 116(2), 220\u2013244.\n\u2014 Classic review of dual-task interference: human central cognitive processing has a serial bottleneck; tasks requiring thought cannot truly run in parallel, only queue."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Rubinstein, J. S., Meyer, D. E., & Evans, J. E. (2001). ",(0,o.jsx)(n.em,{children:"Executive Control of Cognitive Processes in Task Switching."})," Journal of Experimental Psychology: Human Perception and Performance, 27(4), 763\u2013797.\n\u2014 Experimental measurement of task-switching costs: every switch carries a measurable time cost, rising with task complexity and unfamiliarity."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Olsen, D. R., Jr., & Wood, S. B. (2004). ",(0,o.jsx)(n.em,{children:"Fan-out: Measuring Human Control of Multiple Robots."})," CHI '04, 231\u2013238. ACM.\n\u2014 Proposes the fan-out model: the number of autonomous systems one person can operate depends on the ratio of neglect time to interaction time; later extensions incorporating wait times and switching costs lower the feasible fan-out."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Mark, G., Gudith, D., & Klocke, U. (2008). ",(0,o.jsx)(n.em,{children:"The Cost of Interrupted Work: More Speed and Stress."})," CHI '08, 107\u2013110. ACM.\n\u2014 Classic interruption experiment: interrupted workers compensate with faster work, at the cost of significantly higher stress, frustration, and time pressure."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Reinertsen, D. G. (2009). ",(0,o.jsx)(n.em,{children:"The Principles of Product Development Flow: Second Generation Lean Product Development."})," Celeritas Publishing.\n\u2014 Systematically brings queueing theory into product-development management: as utilization approaches 100%, waiting time explodes nonlinearly; scheduling to full utilization guarantees delay."]}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(n.h3,{id:"the-professionalism-thread-items-3437",children:"The Professionalism Thread (items 34\u201337)"}),"\n",(0,o.jsx)(n.p,{children:"The four items below form the professionalism argument running through Layers Three, Four, Six, and Seven. They are grouped thematically rather than ordered by first mention."}),"\n",(0,o.jsxs)(n.ol,{start:"34",children:["\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Freidson, E. (2001). ",(0,o.jsx)(n.em,{children:"Professionalism: The Third Logic."})," University of Chicago Press.\n\u2014 Proposes three logics for coordinating work: the market, bureaucracy, and professionalism. The professional logic holds only under occupational control\u2014the professional community, rather than the employer or the price, defines competent practice and acceptable risk, and grants practitioners corresponding discretion."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Abbott, A. (1988). ",(0,o.jsx)(n.em,{children:"The System of Professions: An Essay on the Division of Expert Labor."})," University of Chicago Press.\n\u2014 Professional standing derives from exclusive jurisdiction over a body of abstract knowledge; conflicts between occupations are fundamentally jurisdictional boundary disputes. Used here to explain why boundary roles lacking jurisdiction are structurally suppressed in rank."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Evetts, J. (2003). ",(0,o.jsx)(n.em,{children:"The Sociological Analysis of Professionalism: Occupational Change in the Modern World."})," International Sociology, 18(2).\n\u2014 Distinguishes organizational professionalism (a discourse of control imposed from above by managers, operating through rational-legal decision-making, hierarchical authority, and standardized procedure) from occupational professionalism (control from within the professional community, encompassing discretion and self-regulation)."]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Fournier, V. (1999). ",(0,o.jsx)(n.em,{children:"The Appeal to 'Professionalism' as a Disciplinary Mechanism."})," The Sociological Review, 47(2), 280\u2013307. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1111/1467-954X.00173",children:"https://doi.org/10.1111/1467-954X.00173"}),'\n\u2014 Argues that when the discourse of the "professional" is deployed in occupational domains not traditionally associated with the professions, it functions as a disciplinary logic: it inscribes "autonomous" professional practice within a network of accountability and governs conduct at a distance through the notion of "professional competence"\u2014professional labor is autonomous labor whose conditions of autonomy have already been inscribed into the definition of competence.']}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"verification-notes",children:"Verification Notes"}),"\n",(0,o.jsxs)(n.blockquote,{children:["\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsx)(n.li,{children:'Publication details (title, authors, year) verified online during drafting for items 1, 4, 7, 8, 10, 11, 12, 13, 14, 16, 19, 20, 21, 24, 25, 31. For item 16 (Davies), the UK edition is Profile Books (2024) and the US edition University of Chicago Press (2025); books carry no DOI. DOIs verified for item 4 (10.1145/2025113.2025119), item 7 (10.1145/2884781.2884851), item 11 (10.1145/2884781.2884875), item 21 (10.1073/pnas.2426766122), and item 24 (10.1287/orsc.2.1.71). For item 25, the volume/issue/pages (AMJ 39(5), 1245\u20131264) and the "without slack, experimentation cannot be sustained due to high-variance outcomes" mechanism were cross-checked via secondary sources. For item 31, the CHI 2004 pages (231\u2013238), the fan-out/neglect-time/interaction-time definitions, the "later models incorporating wait times and switching costs" extensions (Goodrich et al.), and the "inconsistent fan-out prediction methods" finding (Crandall & Cummings 2007) were all verified. "Losses more than three times the expected loss, over five times in simulations" is from the Rigby et al. abstract. "Not merely irritating \u2026 identity destroying" is a rendering of Kahn et al., p. 6. For item 21, the "lazier / less capable / more replaceable," "harshest evaluations from non-users," and "less willing to disclose" claims were cross-checked against the paper\'s abstract and text and Duke Fuqua\'s official coverage.'}),"\n",(0,o.jsx)(n.li,{children:'For item 8 (O\'Leary et al.), volume/issue/pages were verified, but two DOI variants circulate (10.5465/amr.2011.61031807 and 10.5465/amr.2009.0275), so no DOI is attached here; confirm the official DOI at the AMR site before formal submission. For item 9 (Mortensen & Gardner, HBR), the "81% of managers" figure is relayed via a secondary review (Rishani 2024); check the HBR original before citing formally.'}),"\n",(0,o.jsx)(n.li,{children:"For item 13 (Kahn et al.), the in-text claims that conflict rises with role-set diversity derive from Snoek's (1966) follow-up analysis of the same dataset, and that conflict rises with organizational distance from Miles (1977); the essay attributes them to \"follow-up research\" rather than to Kahn's book. Cite Snoek (1966) and Miles (1977) directly if named attribution is needed."}),"\n",(0,o.jsx)(n.li,{children:"Item 15 (Babcock et al., AER) is well known but its volume/pages were not re-verified against the AER original during drafting. Reilly's \"Being Glue\" is a practitioner talk/essay (noidea.dog/glue), not academic literature; it is cited as a practitioner perspective and not listed among formal references; \"done by a senior person it's leadership; done by a junior person it's 'not technical enough'\" is a paraphrase of its argument. Items 22 (Bateson et al.) and 23 (Argyris) are textbook classics whose volume/pages were not re-verified; Bateson's double bind originates in clinical psychology, and this essay borrows only its \"contradictory injunctions + undiscussable contradiction\" structure, as noted in the reference annotation. A 2026 arXiv preprint reports behavioral-experiment evidence that participants will incur personal costs to punish peers who use LLMs (punishment rising with usage intensity), directionally consistent with item 21, but it is not cited here as it has not undergone peer review."}),"\n",(0,o.jsx)(n.li,{children:"Bibliographic details for items 5 (Mockus 2010) and 6 (Mockus 2009) appear consistently across multiple papers' reference lists but were not checked against the ACM originals during drafting; verify before formal submission."}),"\n",(0,o.jsx)(n.li,{children:"Items 2 (Darley & Latan\xe9), 3 (Bryar & Carr), 17 (Hood), and 18 (Pierce et al.) are textbook classics or well-known publications; volume/page details were not re-verified during drafting."}),"\n",(0,o.jsxs)(n.li,{children:["Weinberg's \"each additional concurrent project costs roughly 20% of one's time to switching\" is from ",(0,o.jsx)(n.em,{children:"Quality Software Management, Vol. 1: Systems Thinking"})," (Dorset House, 1992); it is a practitioner heuristic, not rigorous evidence, is flagged as such in the text, and is not listed among formal references."]}),"\n",(0,o.jsx)(n.li,{children:"Apple's DRI practice is widely described in industry reporting and secondary accounts (e.g., Fortune's coverage of Apple's management system), but Apple has published no first-party documentation; the essay treats it as industry common knowledge without binding it to a specific source."}),"\n",(0,o.jsx)(n.li,{children:'"The A column of a RACI can hold only one name" is standard project-management practice found in PMI and similar training materials; no specific paper is cited.'}),"\n",(0,o.jsxs)(n.li,{children:["\"Collective code ownership\" is an Extreme Programming practice tradition (Beck et al.), mentioned as conceptual context without a specific citation. The classification \"single owner = bureaucratic solution, laissez-faire collective = market solution, professional = third road\" is this essay's own derivation from Freidson's three-logics frame, not a taxonomy stated in Freidson's text; the Linux subsystem maintainer and open-source maintainership examples are the essay's own. Ostrom's work on commons governance (",(0,o.jsx)(n.em,{children:"Governing the Commons"}),", 1990) is invoked as a conceptual parallel, not verified item by item during drafting, and is not listed among formal references."]}),"\n",(0,o.jsxs)(n.li,{children:['Verification status of the professionalism thread (items 34\u201337): for item 37 (Fournier), the volume/issue/pages (The Sociological Review, 47(2), 280\u2013307) and DOI (10.1111/1467-954X.00173) were verified, and the "disciplinary logic," "governs conduct at a distance," and "conditions of autonomy already inscribed in professional competence" formulations are paraphrased against the paper\'s abstract. For item 36 (Evetts), the organizational/occupational professionalism distinction and its characterization as a "discourse of control" were cross-checked across multiple secondary sources, ',(0,o.jsx)(n.strong,{children:"but the volume/issue pages were not verified against the original, so no page range is given"}),"; note also that Evetts restates the same distinction across works dated 2003, 2009, 2011, and 2013, and citing papers disagree on which to cite\u2014select one edition and verify before formal submission. Items 34 (Freidson) and 35 (Abbott) are standard monographs in the field; editions and page numbers were not re-verified."]}),"\n",(0,o.jsx)(n.li,{children:'The analogies of the structural engineer stamping drawings she did not draft and the captain answering for the aircraft, along with the formulations "the responsibility is professional, the authority is bureaucratic," "AI\'s threat is stripping the occupation of its authority to define competence," and "professionalism is at once the organization\'s cheapest instrument of discipline and the employee\'s only language of resistance," are this essay\'s own arguments derived from the frames of Freidson, Evetts, and Fournier, not citations. "A jurisdictional ruling, delivered in the form of a performance review" is this essay\'s extension of Abbott\'s frame.'}),"\n",(0,o.jsx)(n.li,{children:'"Delegating decisions to algorithms is the most convenient way to build an accountability sink" is an extension of Davies\'s argument found in the book\'s critical reception (the book itself connects algorithmic decision-making to accountability sinks); it is presented as this essay\'s own reasoning, without quotation marks. "The allocation sheet manufactures an accounting illusion," "a middleman\'s output is inherently counterfactual," "the systematic depreciation of the organization\'s scarcest role," and similar formulations are this essay\'s own arguments, not citations.'}),"\n"]}),"\n"]})]})}function d(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var i=t(96540);let o={},s=i.createContext(o);function a(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);